// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        uint256 blockNum = block.number + 1;
        vm.roll(blockNum + 1);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(blockNum)));

        uint256 balBefore = actor.balance;
        vm.prank(actor);
        c.settle();
        uint256 balAfter = actor.balance;

        if (guess == answer) {
            assertTrue(balAfter == balBefore + 2 ether);
        } else {
            assertTrue(balAfter == balBefore);
        }
    }
}
